scripts.args_schema:
{
  "type": "object",
  "properties": {
    "keyword": {
      "type": "string",
      "description": "一组知网主题检索词"
    },
    "page": {
      "type": "integer",
      "minimum": 1,
      "description": "页码，默认 1"
    }
  },
  "required": [
    "keyword"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "filename": {
      "type": "string",
      "description": "知网搜索结果中该文献的 CookieName 标识"
    }
  },
  "required": [
    "filename"
  ],
  "additionalProperties": false
}
